/**
 * Maps an original gallery photo (e.g. "/gallery/3.jpeg") to a resized WebP variant
 * generated by `npm run images`: "sm" (800px, grids and thumbnails) or "lg" (1600px, lightbox).
 * Anything outside /gallery is returned unchanged.
 */
export function imageVariant(src: string, size: "sm" | "lg"): string {
  const match = src.match(/^\/gallery\/([^/]+)\.(jpe?g|png)$/i);
  return match ? `/gallery/${size}/${match[1]}.webp` : src;
}
